"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["49724"],{39061(e){e.exports=JSON.parse('{"id":"FIN-1071","slug":"cost-center","term":"Cost Center","also_known_as":[],"difficulty":"Advanced","definition":"A cost center is a department or unit of a business whose manager is responsible for controlling costs, but not for generating revenue or profit.","explanation":["Many parts of a business do not earn revenue directly. Examples include human resources, finance, IT, maintenance and many production departments. These are often treated as cost centers.","Cost center managers are evaluated mainly on how well they control spending, usually by comparing actual costs with budget and with the level of service or output they provide.","For example, the IT department might have an annual budget of 2,000,000. Its manager is judged on keeping costs within budget while maintaining the systems the business relies on.","Treating a department as a cost center can encourage cost discipline, but it may also lead managers to cut spending in ways that harm the wider business, such as reducing maintenance and causing breakdowns later. For this reason, cost targets are usually paired with service-level or quality measures. Some companies charge other departments for internal services, turning certain cost centers into units that recover their costs."],"note":"","total":1500,"prev":{"slug":"cost-basis","term":"Cost Basis"},"next":{"slug":"cost-driver","term":"Cost Driver"}}')}}]);